#!/usr/bin/env python3
"""Compute deterministic ground truth for CSX-299_Q1."""

from __future__ import annotations

import html
import json
import math
import re
from pathlib import Path


TASK_ID = "CSX-299_Q1"
EVENT_ID = "CSX-299"
TARGET_FAMILY = "patagonian_dust_streamer_dry_transport_threshold_proof"

SOURCE_FILES = [
    "metadata/event.json",
    "data/event_reports/event_reports_003_Locked_event_anchor_Patagonian_dust_streamers.json",
    "data/event_reports/event_reports_004_NASA_EO_Patagonian_Dust_Streamers.html",
    "data/physical_hazard/physical_hazard_003_ERA5-Land_hourly_aggregate_stats.json",
    "data/physical_hazard/physical_hazard_005_GPM_IMERG_V07_event_accumulated_precipitation.json",
    "data/physical_hazard/physical_hazard_007_CHIRPS_daily_event_accumulated_precipitation.json",
    "data/air_quality/air_quality_001_05_open_meteo_air_quality.json.json",
]

RUBRIC = {
    "total_points": 20,
    "criteria": [
        {
            "name": "Return schema",
            "points": 3,
            "description": "Returns exactly the six requested JSON fields with numeric rounding and the final label.",
        },
        {
            "name": "Dryness calculation",
            "points": 4,
            "description": "Uses the three mean precipitation products, computes pmax_mm, and counts all three below 1.0 mm.",
        },
        {
            "name": "Wind-vector proof",
            "points": 3,
            "description": "Applies sqrt(u_mean^2 + v_mean^2), reports 1.758 m/s within tolerance, and tests the 1.5 m/s threshold.",
        },
        {
            "name": "Transport threshold",
            "points": 3,
            "description": "Extracts the 120 km report-context lower bound and verifies that it satisfies the transport-context rule without treating it as same-day measured transport.",
        },
        {
            "name": "PM availability fraction",
            "points": 3,
            "description": "Counts 0 non-null PM10, PM2.5, and dust values across 72 hourly slots and computes pm_obs_frac = 0.0.",
        },
        {
            "name": "Deterministic conclusion",
            "points": 3,
            "description": "Combines all threshold states to produce dry_wind_conditions_with_report_context_transport_not_measured_pm.",
        },
        {
            "name": "No unsupported escalation",
            "points": 1,
            "description": "Avoids adding casualty, closure, asset-loss, or measured concentration claims not implied by the calculations.",
        },
    ],
}


def read_json(path: Path) -> dict:
    return json.loads(path.read_text(encoding="utf-8-sig"))


def read_text(path: Path) -> str:
    return path.read_text(encoding="utf-8-sig", errors="replace")


def clean_html_text(text: str) -> str:
    text = re.sub(r"(?is)<script.*?</script>|<style.*?</style>", " ", text)
    text = re.sub(r"(?is)<[^>]+>", " ", text)
    text = html.unescape(text)
    return re.sub(r"\s+", " ", text).strip()


def count_non_null(values: list) -> int:
    return sum(1 for value in values if value is not None)


def main() -> None:
    task_dir = Path(__file__).resolve().parent
    repo_root = task_dir.parents[2]
    package_dir = repo_root / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID

    event = read_json(package_dir / "metadata" / "event.json")
    anchor = read_json(package_dir / SOURCE_FILES[1])
    report_text = clean_html_text(read_text(package_dir / SOURCE_FILES[2]))
    era5 = read_json(package_dir / SOURCE_FILES[3])
    gpm = read_json(package_dir / SOURCE_FILES[4])
    chirps = read_json(package_dir / SOURCE_FILES[5])
    air_quality = read_json(package_dir / SOURCE_FILES[6])

    era5_stats = era5["stats"]
    precip_means = {
        "era5_land": era5_stats["precipitation_sum_mm_mean"],
        "gpm": gpm["stats"]["gpm_event_precip_mm_mean"],
        "chirps": chirps["stats"]["chirps_event_precip_mm_mean"],
    }
    pmax_mm = max(precip_means.values())
    dry_count = sum(1 for value in precip_means.values() if value < 1.0)

    u_mean = era5_stats["u_component_of_wind_10m_mean"]
    v_mean = era5_stats["v_component_of_wind_10m_mean"]
    wind_m_s = math.hypot(u_mean, v_mean)

    distance_match = re.search(r"more than\s+([0-9]+)\s+kilometers", report_text)
    transport_km_lb = int(distance_match.group(1)) if distance_match else None

    hourly = air_quality["hourly"]
    pm_fields = ["pm10", "pm2_5", "dust"]
    pm_total_slots = len(hourly["time"]) * len(pm_fields)
    pm_non_null = sum(count_non_null(hourly[field]) for field in pm_fields)
    pm_obs_frac = pm_non_null / pm_total_slots

    dry_pass = pmax_mm < 1.0 and dry_count == 3
    wind_pass = wind_m_s >= 1.5
    transport_pass = transport_km_lb is not None and transport_km_lb >= 120
    pm_burden_pass = pm_obs_frac > 0
    conclusion = (
        "dry_wind_conditions_with_report_context_transport_not_measured_pm"
        if dry_pass and wind_pass and transport_pass and not pm_burden_pass
        else "rule_not_satisfied"
    )
    report_context_date = "2020-03-07" if re.search(r"March\s+7", report_text, flags=re.IGNORECASE) else "report_context"
    evidence_windows = {
        "event_window": {
            "start": anchor["temporal_window"]["start_date"],
            "end": anchor["temporal_window"]["end_date"],
        },
        "precip_wind_window": {
            "start": era5["start"],
            "end": era5["end"],
        },
        "transport_report_context_date": report_context_date,
    }

    primary_gt = {
        "evidence_windows": evidence_windows,
        "pmax_mm": round(pmax_mm, 3),
        "dry_count": dry_count,
        "wind_m_s": round(wind_m_s, 3),
        "transport_km_lb": transport_km_lb,
        "pm_obs_frac": round(pm_obs_frac, 3),
        "conclusion": conclusion,
    }

    output = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "numeric",
        "evaluation_mode": "deterministic",
        "difficulty_level": "L3",
        "target_family": TARGET_FAMILY,
        "primary_gt": primary_gt,
        "tolerances": {
            "pmax_mm": 0.001,
            "wind_m_s": 0.001,
            "pm_obs_frac": 0.001,
            "integer_fields": "exact",
            "conclusion": "exact",
        },
        "decision_rule": {
            "dry_pass": "max(mean_precip_mm) < 1.0 and dry_count == 3",
            "wind_pass": "sqrt(u_mean^2 + v_mean^2) >= 1.5",
            "transport_pass": "reported_lower_bound_km >= 120",
            "pm_burden_pass": "non_null_pm_pm25_dust / total_slots > 0",
            "final": "dry_pass and wind_pass and report_context_transport_pass and not pm_burden_pass",
        },
        "key_values": {
            "precip_mean_mm": precip_means,
            "wind_component_mean_m_s": {"u": u_mean, "v": v_mean},
            "pm_counts": {
                "hours": len(hourly["time"]),
                "fields": len(pm_fields),
                "non_null": pm_non_null,
                "total_slots": pm_total_slots,
            },
            "report_checks": {
                "transport_report_context_date": report_context_date,
                "source_lake": "Lago Colhue" in report_text or "Lago Colhu" in report_text,
                "exposed_silt": "loose silt exposed at the surface" in report_text,
                "wind_aligned": "aligned with the wind direction" in report_text,
                "transport_km_lb": transport_km_lb,
            },
        },
        "rubric": RUBRIC,
        "event": {
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "event_date_or_window": anchor["temporal_window"],
            "region": event["region"],
            "scale": event["scale"],
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
            "notes": "Deterministic formulas are computed from local package values; no network access is used.",
        },
    }

    (task_dir / "computed_gt.json").write_text(
        json.dumps(output, indent=2, ensure_ascii=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
